refentry.refsect1:
&reftitle.description;
arrayarray_column arrayarray intstringnullcolumn_key intstringnullindex_key&null;
array_column devuelve los valores de una columna de array, identificada por la clave column_key. Opcionalmente, se puede proporcionar un argumento index_key para indexar los valores en el array devuelto por los valores de la columna index_key del array de entrada.
array se trata como una lista de filas, cada una de las cuales es a su vez un array o un objeto; una columna es la entrada o propiedad que column_key nombra en cada fila. Las filas que no son ni un array ni un objeto, y las filas en las que dicha entrada o propiedad está ausente, se omiten sin diagnóstico. Las claves de array nunca se conservan.

  &reftitle.examples;



    Recupera la columna de los nombres


<?php

// Array que representa un conjunto de registros de una base de datos
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$first_names = array_column($records, 'first_name');
print_r($first_names);

?>


    &example.outputs;


Array
(
    [0] => John
    [1] => Sally
    [2] => Jane
    [3] => Peter
)








     Recupera la columna de los apellidos, indexada por la columna "id"



<?php

// Utilizando el array del ejemplo #1
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$last_names = array_column($records, 'last_name', 'id');
print_r($last_names);

?>


    &example.outputs;


Array
(
    [2135] => Doe
    [3245] => Smith
    [5342] => Jones
    [5623] => Doe
)








     Recupera la columna de los nombres de usuario desde la propiedad pública
     "username" de un objeto



<?php

class User
{
    public $username;

    public function __construct(string $username)
    {
        $this->username = $username;
    }
}

$users = [
    new User('user 1'),
    new User('user 2'),
    new User('user 3'),
];

print_r(array_column($users, 'username'));

?>


    &example.outputs;


Array
(
    [0] => user 1
    [1] => user 2
    [2] => user 3
)








     Recupera la columna de nombres desde la propiedad privada "name" de un
     objeto utilizando los métodos mágicos __isset()
     y __get()



<?php

class Person
{
    private $name;

    public function __construct(string $name)
    {
        $this->name = $name;
    }

    public function __get($prop)
    {
        return $this->$prop;
    }

    public function __isset($prop) : bool
    {
        return isset($this->$prop);
    }
}

$people = [
    new Person('Fred'),
    new Person('Jane'),
    new Person('John'),
];

print_r(array_column($people, 'name'));
?>


    &example.outputs;


Array
(
    [0] => Fred
    [1] => Jane
    [2] => John
)



   Si __isset() no está definido, el objeto
   no contribuye con ninguna entrada al array devuelto.
